-- Complete first-pass editorial content: Metodologias da Educação Infantil + Literatura Infantil.
-- Basis: DCNEI and current national quality/equity guidance for Educação Infantil.
WITH seed(discipline_name,topic_name,position,title,content) AS (VALUES ('Metodologias da Educação Infantil','Organização de tempos e espaços',1,'Conceito central','Tempo e espaço são elementos pedagógicos. A organização da rotina e dos ambientes influencia autonomia, interação, exploração, descanso e possibilidades de aprendizagem.'),
('Metodologias da Educação Infantil','Organização de tempos e espaços',2,'Rotina e flexibilidade','Uma rotina dá previsibilidade, mas precisa admitir flexibilidade diante dos ritmos, interesses e acontecimentos do grupo.'),
('Metodologias da Educação Infantil','Organização de tempos e espaços',3,'Espaço como mediador','Materiais, circulação, iluminação, acessibilidade e disposição dos objetos comunicam expectativas e criam ou limitam oportunidades de ação.'),
('Metodologias da Educação Infantil','Organização de tempos e espaços',4,'Exemplo para visualizar','Um ambiente com materiais ao alcance das crianças favorece escolhas e autonomia; um ambiente em que tudo depende do adulto produz outras possibilidades de participação.'),
('Metodologias da Educação Infantil','Organização de tempos e espaços',5,'Situação para analisar','A rotina reserva pouco tempo para exploração livre porque todas as transições são rígidas. Analise como isso altera as experiências das crianças.'),
('Metodologias da Educação Infantil','Organização de tempos e espaços',6,'Erro comum','Confundir organização com excesso de controle. Uma rotina organizada não precisa tornar todas as ações previsíveis ou iguais.'),
('Metodologias da Educação Infantil','Organização de tempos e espaços',7,'Aprofundamento','As diretrizes nacionais de 2024 incluem ambientes educativos, infraestrutura e processos pedagógicos entre as dimensões da qualidade e equidade da Educação Infantil. citeturn381514search45'),
('Metodologias da Educação Infantil','Organização de tempos e espaços',8,'Aplicação pedagógica','Ao planejar o ambiente, pergunte quais ações ele favorece, quais barreiras cria, que materiais estão disponíveis e como diferentes crianças poderão participar.'),
('Metodologias da Educação Infantil','Organização de tempos e espaços',9,'Síntese','Organizar tempos e espaços é uma decisão curricular e pedagógica porque altera diretamente as possibilidades de experiência, interação e aprendizagem.'),
('Metodologias da Educação Infantil','Organização de tempos e espaços',10,'Para revisar','Escolha um espaço da Educação Infantil e explique como sua organização pode ampliar autonomia.'),
('Metodologias da Educação Infantil','Planejamento de experiências',1,'Conceito central','Planejar experiências significa pensar intencionalidades, materiais, tempos, espaços, interações e possibilidades de ação das crianças, sem reduzir a proposta a uma ficha de atividades.'),
('Metodologias da Educação Infantil','Planejamento de experiências',2,'Intencionalidade pedagógica','Intencionalidade define o que o professor pretende favorecer, mas não determina cada resposta da criança. A experiência mantém espaço para investigação e descoberta.'),
('Metodologias da Educação Infantil','Planejamento de experiências',3,'Partir da observação','Interesses, hipóteses, dúvidas e formas de participação observadas no grupo ajudam a construir experiências mais significativas.'),
('Metodologias da Educação Infantil','Planejamento de experiências',4,'Exemplo para visualizar','Se crianças demonstram curiosidade por sementes, o professor pode organizar experiências de plantio, comparação, observação, registros e conversa, acompanhando o que surge no processo.'),
('Metodologias da Educação Infantil','Planejamento de experiências',5,'Situação para analisar','Uma professora planeja cinco atividades sem observar o grupo. Analise como o planejamento pode perder conexão com as necessidades e interesses reais das crianças.'),
('Metodologias da Educação Infantil','Planejamento de experiências',6,'Erro comum','Confundir planejamento com antecipação detalhada de cada fala ou resposta possível.'),
('Metodologias da Educação Infantil','Planejamento de experiências',7,'Aprofundamento','O currículo da Educação Infantil deve articular experiências, interações e direitos de aprendizagem. O planejamento é o meio de transformar essas referências em situações concretas. citeturn391584search6'),
('Metodologias da Educação Infantil','Planejamento de experiências',8,'Aplicação pedagógica','Para cada experiência, registre: intencionalidade, materiais, organização do ambiente, possibilidades de participação e o que será observado.'),
('Metodologias da Educação Infantil','Planejamento de experiências',9,'Síntese','Planejar é criar condições para determinadas aprendizagens e experiências, mantendo abertura para o que acontece durante a prática.'),
('Metodologias da Educação Infantil','Planejamento de experiências',10,'Para revisar','Qual é a diferença entre planejar uma experiência e planejar uma atividade fechada com resultado único?'),
('Metodologias da Educação Infantil','Interações e mediação',1,'Conceito central','Mediação pedagógica envolve criar condições para que as crianças explorem, pensem, comuniquem-se e ampliem experiências. Intervir não significa controlar todas as ações.'),
('Metodologias da Educação Infantil','Interações e mediação',2,'Observar antes de intervir','A observação ajuda a perceber o que a criança está tentando fazer e qual apoio pode ser útil. Uma intervenção precipitada pode interromper uma descoberta.'),
('Metodologias da Educação Infantil','Interações e mediação',3,'Perguntas e materiais','Perguntas abertas, materiais variados e mudanças no ambiente podem ampliar investigações sem entregar respostas prontas.'),
('Metodologias da Educação Infantil','Interações e mediação',4,'Exemplo para visualizar','Diante de uma construção que cai repetidamente, o professor pode perguntar o que a criança observa e oferecer materiais diferentes para que ela teste novas possibilidades.'),
('Metodologias da Educação Infantil','Interações e mediação',5,'Situação para analisar','O adulto resolve todos os problemas da atividade para acelerar o andamento. Analise o que a criança deixa de experimentar quando o professor ocupa todo o espaço de decisão.'),
('Metodologias da Educação Infantil','Interações e mediação',6,'Erro comum','Entender mediação como explicar tudo ou corrigir imediatamente toda produção infantil.'),
('Metodologias da Educação Infantil','Interações e mediação',7,'Aprofundamento','As diretrizes de qualidade valorizam ambientes e interações educativas planejadas para promover desenvolvimento e aprendizagem. citeturn381514search47'),
('Metodologias da Educação Infantil','Interações e mediação',8,'Aplicação pedagógica','Quando intervir, registre o que observou, a hipótese sobre a necessidade da criança e por que escolheu determinada intervenção.'),
('Metodologias da Educação Infantil','Interações e mediação',9,'Síntese','Mediação qualificada amplia possibilidades sem substituir a ação da criança. O professor cria condições, observa e ajusta o percurso.'),
('Metodologias da Educação Infantil','Interações e mediação',10,'Para revisar','Descreva uma intervenção do professor que apoie uma criança sem resolver o problema por ela.'),
('Metodologias da Educação Infantil','Projetos e experiências de aprendizagem',1,'Conceito central','Projetos podem organizar investigações prolongadas em torno de perguntas, interesses ou problemas significativos, articulando diferentes linguagens e experiências.'),
('Metodologias da Educação Infantil','Projetos e experiências de aprendizagem',2,'Projeto não é sequência de tarefas','Um projeto se caracteriza pela investigação e construção de percurso, não apenas por várias atividades sobre o mesmo tema.'),
('Metodologias da Educação Infantil','Projetos e experiências de aprendizagem',3,'Participação das crianças','Crianças podem levantar perguntas, escolher caminhos, observar, registrar, comparar e comunicar descobertas dentro das possibilidades de sua faixa etária.'),
('Metodologias da Educação Infantil','Projetos e experiências de aprendizagem',4,'Exemplo para visualizar','Um projeto sobre água pode envolver observação de usos, experiências com recipientes, desenhos, relatos, medidas, histórias e reflexão sobre cuidado.'),
('Metodologias da Educação Infantil','Projetos e experiências de aprendizagem',5,'Situação para analisar','O professor decide todo o projeto sozinho e apenas distribui tarefas. Analise se há investigação e participação reais ou apenas execução de uma programação adulta.'),
('Metodologias da Educação Infantil','Projetos e experiências de aprendizagem',6,'Erro comum','Usar “projeto” como nome para qualquer sequência temática, sem problema ou investigação que dê sentido ao percurso.'),
('Metodologias da Educação Infantil','Projetos e experiências de aprendizagem',7,'Aprofundamento','A integração de diferentes linguagens e experiências aparece nas orientações curriculares da Educação Infantil, que valorizam narrativas, linguagem oral e escrita, experiências corporais, sensoriais e expressivas. citeturn391584search46'),
('Metodologias da Educação Infantil','Projetos e experiências de aprendizagem',8,'Aplicação pedagógica','Defina uma questão mobilizadora, registre hipóteses das crianças, organize experiências e reavalie o caminho conforme novas perguntas surgirem.'),
('Metodologias da Educação Infantil','Projetos e experiências de aprendizagem',9,'Síntese','Projetos dão continuidade à investigação e permitem integrar aprendizagens sem fragmentar a experiência infantil em conteúdos isolados.'),
('Metodologias da Educação Infantil','Projetos e experiências de aprendizagem',10,'Para revisar','O que diferencia um projeto de uma sequência de atividades sobre um mesmo tema?'),
('Metodologias da Educação Infantil','Observação e documentação pedagógica',1,'Conceito central','Observação pedagógica busca compreender processos; documentação reúne registros que tornam esses processos visíveis e ajudam a planejar novas experiências.'),
('Metodologias da Educação Infantil','Observação e documentação pedagógica',2,'Foco da observação','Observar com intenção significa escolher aspectos relevantes: linguagem, interação, estratégias, interesses, hipóteses, autonomia ou modos de participação.'),
('Metodologias da Educação Infantil','Observação e documentação pedagógica',3,'Registros interpretativos','Um bom registro separa o que foi observado da interpretação do professor, permitindo revisar hipóteses posteriormente.'),
('Metodologias da Educação Infantil','Observação e documentação pedagógica',4,'Exemplo para visualizar','Em vez de registrar “Maria não sabe contar”, o professor registra quantos objetos ela contou, como organizou a coleção e onde perdeu a correspondência um a um.'),
('Metodologias da Educação Infantil','Observação e documentação pedagógica',5,'Situação para analisar','Um portfólio contém muitas fotos, mas nenhuma informação sobre o que elas mostram ou como influenciaram o planejamento. Analise o limite dessa documentação.'),
('Metodologias da Educação Infantil','Observação e documentação pedagógica',6,'Erro comum','Confundir quantidade de registros com qualidade de documentação pedagógica.'),
('Metodologias da Educação Infantil','Observação e documentação pedagógica',7,'Aprofundamento','As diretrizes de qualidade de 2024 estabelecem acompanhamento permanente das aprendizagens e do desenvolvimento das crianças, articulado a referências curriculares. citeturn381514search47'),
('Metodologias da Educação Infantil','Observação e documentação pedagógica',8,'Aplicação pedagógica','Use registros para construir hipóteses sobre aprendizagem e decidir quais experiências oferecer em seguida. Evite usar a documentação apenas para exposição estética.'),
('Metodologias da Educação Infantil','Observação e documentação pedagógica',9,'Síntese','Documentar é tornar processos compreensíveis para orientar decisões pedagógicas e comunicar percursos de aprendizagem.'),
('Metodologias da Educação Infantil','Observação e documentação pedagógica',10,'Para revisar','Escreva um exemplo de registro descritivo que diferencie observação de interpretação.'),
('Literatura Infantil','Literatura e infância',1,'Conceito central','Literatura infantil oferece experiências de linguagem, imaginação, estética e construção de sentidos. Seu valor não depende de servir como exercício para ensinar outro conteúdo.'),
('Literatura Infantil','Literatura e infância',2,'Experiência estética','Ler literatura envolve acompanhar linguagem, imagens, ritmo, personagens, conflitos e possibilidades interpretativas, permitindo fruição e reflexão.'),
('Literatura Infantil','Literatura e infância',3,'Infância e repertório','O acesso a obras literárias amplia repertório cultural e linguístico, oferecendo experiências que não precisam reproduzir situações cotidianas da criança.'),
('Literatura Infantil','Literatura e infância',4,'Exemplo para visualizar','Um conto pode ser lido para apreciar a narrativa, imaginar outros finais e conversar sobre personagens, sem exigir que toda leitura resulte em uma ficha de perguntas.'),
('Literatura Infantil','Literatura e infância',5,'Situação para analisar','Um livro é escolhido apenas porque contém muitas palavras com determinada letra. Analise o que pode ser perdido quando a obra literária vira instrumento exclusivo de alfabetização.'),
('Literatura Infantil','Literatura e infância',6,'Erro comum','Reduzir literatura a moral da história ou a treino mecânico de habilidades.'),
('Literatura Infantil','Literatura e infância',7,'Aprofundamento','As orientações curriculares da Educação Infantil valorizam experiências com narrativas e interação com linguagem oral e escrita e diferentes suportes e gêneros. citeturn391584search46'),
('Literatura Infantil','Literatura e infância',8,'Aplicação pedagógica','Selecione obras considerando qualidade literária, diversidade e adequação ao grupo; prepare condições de escuta e conversa sem impor uma única interpretação.'),
('Literatura Infantil','Literatura e infância',9,'Síntese','Literatura infantil é experiência artística e cultural. Na escola, deve preservar espaço para imaginação, linguagem, interpretação e fruição.'),
('Literatura Infantil','Literatura e infância',10,'Para revisar','Explique por que uma obra literária não deve ser escolhida somente pela possibilidade de trabalhar uma letra ou conteúdo específico.'),
('Literatura Infantil','Mediação de leitura literária',1,'Conceito central','Mediar leitura literária é criar condições para que as crianças escutem, observem, interpretem, façam perguntas e compartilhem sentidos construídos a partir da obra.'),
('Literatura Infantil','Mediação de leitura literária',2,'Antes, durante e depois','A mediação pode incluir antecipação, observação de imagens, escuta atenta, perguntas abertas e retomadas, mantendo a obra como centro da experiência.'),
('Literatura Infantil','Mediação de leitura literária',3,'Perguntas que ampliam','Perguntas como “o que você percebeu?” ou “o que poderia acontecer?” favorecem interpretação, enquanto perguntas que buscam uma única resposta podem limitar a conversa.'),
('Literatura Infantil','Mediação de leitura literária',4,'Exemplo para visualizar','Depois de uma leitura, crianças apresentam interpretações diferentes sobre uma personagem. O professor retoma elementos do texto e acolhe argumentos sem transformar a conversa em teste de resposta correta.'),
('Literatura Infantil','Mediação de leitura literária',5,'Situação para analisar','A professora interrompe cada página para fazer perguntas até perder o ritmo narrativo. Analise como equilibrar mediação e continuidade da experiência literária.'),
('Literatura Infantil','Mediação de leitura literária',6,'Erro comum','Usar a leitura literária apenas como etapa para uma atividade posterior.'),
('Literatura Infantil','Mediação de leitura literária',7,'Aprofundamento','A formação de leitores começa com experiências significativas e contato recorrente com diferentes textos. A mediação ajuda a construir repertório e participação na cultura escrita.'),
('Literatura Infantil','Mediação de leitura literária',8,'Aplicação pedagógica','Escolha previamente quais aspectos da obra podem gerar conversa e deixe espaço para perguntas e interpretações inesperadas das crianças.'),
('Literatura Infantil','Mediação de leitura literária',9,'Síntese','Mediação não substitui a leitura: cria condições para que a leitura seja vivida coletivamente e aprofundada.'),
('Literatura Infantil','Mediação de leitura literária',10,'Para revisar','Escreva duas perguntas abertas que poderiam ampliar uma conversa sobre uma história.'),
('Literatura Infantil','Gêneros e formas literárias para crianças',1,'Conceito central','Contos, poemas, parlendas, narrativas ilustradas e outras formas literárias oferecem modos diferentes de experimentar linguagem, ritmo, imagens e ficção.'),
('Literatura Infantil','Gêneros e formas literárias para crianças',2,'Diversidade de formas','Variar gêneros e formas amplia repertório e permite que crianças encontrem diferentes modos de relação com a literatura.'),
('Literatura Infantil','Gêneros e formas literárias para crianças',3,'Texto e imagem','Em livros ilustrados, imagem também participa da construção de sentido. A criança pode observar relações, contrastes e informações que não estão explícitas no texto verbal.'),
('Literatura Infantil','Gêneros e formas literárias para crianças',4,'Exemplo para visualizar','Uma narrativa sem texto verbal pode ser “lida” por meio das imagens, permitindo que as crianças construam hipóteses e narrativas próprias.'),
('Literatura Infantil','Gêneros e formas literárias para crianças',5,'Situação para analisar','Uma professora apresenta somente contos longos durante meses. Analise como poemas, parlendas e livros ilustrados poderiam diversificar experiências de linguagem.'),
('Literatura Infantil','Gêneros e formas literárias para crianças',6,'Erro comum','Classificar gêneros apenas por tamanho ou tema, sem considerar como a linguagem e a forma constroem sentidos.'),
('Literatura Infantil','Gêneros e formas literárias para crianças',7,'Aprofundamento','As referências curriculares da Educação Infantil mencionam diferentes gêneros textuais orais e escritos e diferentes suportes, reforçando a diversidade de experiências de linguagem. citeturn391584search46'),
('Literatura Infantil','Gêneros e formas literárias para crianças',8,'Aplicação pedagógica','Organize uma pequena diversidade de obras para o grupo e observe quais formas provocam diferentes modos de escuta, participação e criação.'),
('Literatura Infantil','Gêneros e formas literárias para crianças',9,'Síntese','Gêneros e formas literárias oferecem experiências distintas; repertório diversificado amplia possibilidades de formação leitora.'),
('Literatura Infantil','Gêneros e formas literárias para crianças',10,'Para revisar','Liste quatro formas ou gêneros literários e explique uma experiência diferente que cada um pode oferecer.'),
('Literatura Infantil','Literatura, imaginação e experiência estética',1,'Conceito central','A experiência estética permite entrar em mundos ficcionais, experimentar linguagem e imaginar possibilidades. Ela não precisa produzir uma resposta utilitária imediata.'),
('Literatura Infantil','Literatura, imaginação e experiência estética',2,'Imaginação','Imaginar não significa afastar-se da aprendizagem. A ficção permite combinar experiências, levantar hipóteses, criar perspectivas e experimentar formas de linguagem.'),
('Literatura Infantil','Literatura, imaginação e experiência estética',3,'Fruição e conversa','A criança pode gostar, estranhar, rir, discordar ou ficar em silêncio diante de uma obra. A mediação pedagógica acolhe essas respostas e ajuda a ampliar a experiência.'),
('Literatura Infantil','Literatura, imaginação e experiência estética',4,'Exemplo para visualizar','Depois de uma história fantástica, crianças inventam explicações diferentes para um acontecimento. O professor valoriza as hipóteses e retoma elementos da narrativa.'),
('Literatura Infantil','Literatura, imaginação e experiência estética',5,'Situação para analisar','Uma atividade exige que todas as crianças desenhem exatamente a mesma cena do livro. Analise como isso pode limitar imaginação e autoria.'),
('Literatura Infantil','Literatura, imaginação e experiência estética',6,'Erro comum','Confundir experiência estética com atividade sem intencionalidade. O professor pode ter objetivos de formação leitora sem controlar cada resultado.'),
('Literatura Infantil','Literatura, imaginação e experiência estética',7,'Aprofundamento','As experiências de narrativas, apreciação e diferentes linguagens aparecem entre as práticas pedagógicas previstas nas orientações curriculares da Educação Infantil. citeturn391584search46'),
('Literatura Infantil','Literatura, imaginação e experiência estética',8,'Aplicação pedagógica','Crie situações em que crianças possam retomar a obra por meio de desenho, dramatização, conversa ou reconto sem exigir reprodução idêntica.'),
('Literatura Infantil','Literatura, imaginação e experiência estética',9,'Síntese','Literatura amplia imaginação e experiência estética quando preserva espaço para criação, interpretação e sensibilidade.'),
('Literatura Infantil','Literatura, imaginação e experiência estética',10,'Para revisar','Explique por que uma atividade sobre literatura pode ter intencionalidade pedagógica sem exigir uma única resposta correta.'),
('Literatura Infantil','Seleção de obras e formação do leitor',1,'Conceito central','Selecionar obras exige considerar qualidade literária, diversidade de autores e culturas, complexidade adequada ao grupo e possibilidades de mediação.'),
('Literatura Infantil','Seleção de obras e formação do leitor',2,'Critérios de seleção','Observe linguagem, projeto gráfico, ilustrações, construção narrativa, diversidade de perspectivas, materialidade do livro e potencial de conversa.'),
('Literatura Infantil','Seleção de obras e formação do leitor',3,'Acervo e diversidade','Um acervo diversificado oferece diferentes experiências culturais e evita apresentar um único padrão de infância, família, território ou identidade.'),
('Literatura Infantil','Seleção de obras e formação do leitor',4,'Exemplo para visualizar','Ao montar uma cesta de leitura, o professor combina poesia, contos, livros ilustrados e diferentes autores, revisitando obras ao longo do período.'),
('Literatura Infantil','Seleção de obras e formação do leitor',5,'Situação para analisar','Uma escola escolhe somente livros usados em exercícios de alfabetização. Analise como critérios literários podem ampliar o acervo.'),
('Literatura Infantil','Seleção de obras e formação do leitor',6,'Erro comum','Escolher livros somente por faixa etária ou pela possibilidade de ensinar um conteúdo específico.'),
('Literatura Infantil','Seleção de obras e formação do leitor',7,'Aprofundamento','A política de Educação Infantil valoriza acesso a experiências de linguagem, narrativas e diferentes suportes e gêneros. citeturn391584search46'),
('Literatura Infantil','Seleção de obras e formação do leitor',8,'Aplicação pedagógica','Registre por que uma obra foi escolhida, que experiência ela pode proporcionar e como a mediação pode respeitar diferentes respostas das crianças.'),
('Literatura Infantil','Seleção de obras e formação do leitor',9,'Síntese','Formar leitores depende de acesso, diversidade, recorrência e mediação de obras significativas.'),
('Literatura Infantil','Seleção de obras e formação do leitor',10,'Para revisar','Liste três critérios literários que você usaria para escolher uma obra para a Educação Infantil.'))
UPDATE public.material_sections ms
SET title=s.title,content=s.content,section_type=CASE s.position WHEN 1 THEN 'concept' WHEN 2 THEN 'explanation' WHEN 3 THEN 'explanation' WHEN 4 THEN 'examples' WHEN 5 THEN 'examples' WHEN 6 THEN 'common_mistakes' WHEN 7 THEN 'deepening' WHEN 8 THEN 'deepening' WHEN 9 THEN 'review' ELSE 'review' END
FROM seed s,public.materials m,public.topics t,public.disciplines d
WHERE ms.material_id=m.id AND m.topic_id=t.id AND t.discipline_id=d.id
AND d.name=s.discipline_name AND t.name=s.topic_name AND ms.position=s.position AND m.status='draft';